/**
 * Structured, nested engine failure taxonomy crossing the FFI boundary
 * (Phase 3 / MP-C04, master plan invariant 8).
 *
 * Non-exhaustive BY DESIGN: the Rust-side enum carries
 * `#[non_exhaustive]` so the core can grow categories without breaking
 * in-crate consumers, and the stable numeric codes (see below) are the
 * foreign-side forward-compat currency. TOOLCHAIN NOTE: uniffi 0.28's
 * UDL grammar cannot express `[NonExhaustive]` on the interface syntax
 * used for fielded variants (its attribute validator rejects the
 * combination — verified against uniffi_udl 0.28.3), so the generated
 * bindings are exhaustive until the uniffi upgrade; the Rust enum is
 * `#[non_exhaustive]` as mandated, and new variants MUST only append.
 * Stable numeric codes are exposed Rust-side via
 * `EngineError::stable_code()` (category byte | kind byte | status
 * half-word) — see `rust/src/contract.rs`; the codes are pinned by unit
 * tests and MUST NOT be renumbered.
 *
 * The `Internal` variant is also the panic channel: every UniFFI
 * entrypoint is wrapped in `catch_unwind` and converts a Rust panic
 * into `Internal { error_message, backtrace }` (MP-C06) — a panic never
 * unwinds into Kotlin or Swift.
 */
sealed class EngineException: kotlin.Exception() {
    
    /**
     * Stream acquisition / transport failure. `status` is the HTTP status
     * when a response arrived (0 otherwise); `retry_after` is the
     * server-advised or engine-estimated retry hint in MILLISECONDS.
     */
    class Network(
        
        val `kind`: NetworkErrorKind, 
        
        val `status`: kotlin.UShort, 
        
        val `retryAfter`: kotlin.UInt
        ) : EngineException() {
        override val message
            get() = "kind=${ `kind` }, status=${ `status` }, retryAfter=${ `retryAfter` }"
    }
    
    /**
     * Audio subsystem failure (device, format, clock, underrun, init).
     * `device_id` identifies the HAL device when known.
     */
    class Audio(
        
        val `kind`: AudioErrorKind, 
        
        val `deviceId`: kotlin.String?
        ) : EngineException() {
        override val message
            get() = "kind=${ `kind` }, deviceId=${ `deviceId` }"
    }
    
    /**
     * Device-local encrypted storage failure.
     */
    class Storage(
        
        val `kind`: StorageErrorKind
        ) : EngineException() {
        override val message
            get() = "kind=${ `kind` }"
    }
    
    /**
     * Key material / cipher operation failure.
     */
    class Crypto(
        
        val `kind`: CryptoErrorKind
        ) : EngineException() {
        override val message
            get() = "kind=${ `kind` }"
    }
    
    /**
     * Unexpected internal fault, INCLUDING marshaled Rust panics
     * (`error_message` carries the panic text, `backtrace` the
     * captured stack when available). Requires diagnostics.
     *
     * NAMING NOTE (Phase 5 upstream fix from Beta): the field is
     * deliberately `error_message`, NOT `errorMessage` — uniffi 0.28.3's
     * Kotlin backend emits a `errorMessage`-named constructor property
     * that collides with kotlin.Throwable's shadowed `errorMessage`
     * getter (the generated `InternalException` does not compile as
     * emitted). The rename lets Beta's Gradle
     * `patchDesktopUniffiBindings` shim retire to its documented
     * no-op path instead of patching the raw codegen.
     */
    class Internal(
        
        val `errorMessage`: kotlin.String, 
        
        val `backtrace`: kotlin.String?
        ) : EngineException() {
        override val message
            get() = "errorMessage=${ `errorMessage` }, backtrace=${ `backtrace` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<EngineException> {
        override fun lift(error_buf: RustBuffer.ByValue): EngineException = FfiConverterTypeEngineError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeEngineError : FfiConverterRustBuffer<EngineException> {
    override fun read(buf: ByteBuffer): EngineException {
        

        return when(buf.getInt()) {
            1 -> EngineException.Network(
                FfiConverterTypeNetworkErrorKind.read(buf),
                FfiConverterUShort.read(buf),
                FfiConverterUInt.read(buf),
                )
            2 -> EngineException.Audio(
                FfiConverterTypeAudioErrorKind.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            3 -> EngineException.Storage(
                FfiConverterTypeStorageErrorKind.read(buf),
                )
            4 -> EngineException.Crypto(
                FfiConverterTypeCryptoErrorKind.read(buf),
                )
            5 -> EngineException.Internal(
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: EngineException): ULong {
        return when(value) {
            is EngineException.Network -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterTypeNetworkErrorKind.allocationSize(value.`kind`)
                + FfiConverterUShort.allocationSize(value.`status`)
                + FfiConverterUInt.allocationSize(value.`retryAfter`)
            )
            is EngineException.Audio -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterTypeAudioErrorKind.allocationSize(value.`kind`)
                + FfiConverterOptionalString.allocationSize(value.`deviceId`)
            )
            is EngineException.Storage -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterTypeStorageErrorKind.allocationSize(value.`kind`)
            )
            is EngineException.Crypto -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterTypeCryptoErrorKind.allocationSize(value.`kind`)
            )
            is EngineException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`errorMessage`)
                + FfiConverterOptionalString.allocationSize(value.`backtrace`)
            )
        }
    }

    override fun write(value: EngineException, buf: ByteBuffer) {
        when(value) {
            is EngineException.Network -> {
                buf.putInt(1)
                FfiConverterTypeNetworkErrorKind.write(value.`kind`, buf)
                FfiConverterUShort.write(value.`status`, buf)
                FfiConverterUInt.write(value.`retryAfter`, buf)
                Unit
            }
            is EngineException.Audio -> {
                buf.putInt(2)
                FfiConverterTypeAudioErrorKind.write(value.`kind`, buf)
                FfiConverterOptionalString.write(value.`deviceId`, buf)
                Unit
            }
            is EngineException.Storage -> {
                buf.putInt(3)
                FfiConverterTypeStorageErrorKind.write(value.`kind`, buf)
                Unit
            }
            is EngineException.Crypto -> {
                buf.putInt(4)
                FfiConverterTypeCryptoErrorKind.write(value.`kind`, buf)
                Unit
            }
            is EngineException.Internal -> {
                buf.putInt(5)
                FfiConverterString.write(value.`errorMessage`, buf)
                FfiConverterOptionalString.write(value.`backtrace`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * Reverse control plane: hardware / headset media commands pushed INTO
