/**
 * Push event listener for coalesced engine state (Phase 3 / MP-C02,
 * MP-DEC-04).
 *
 * Register via `StreamifyEngine::add_event_listener`. The engine
 * dispatches `on_engine_event` on a DEDICATED background thread — never
 * the real-time audio thread, never the registration thread, never
 * re-entrantly (a listener that mutates engine state only schedules the
 * next dispatch; it never recurses). Snapshots are coalesced: bursts of
 * state changes collapse into one dispatch carrying the newest revision.
 *
 * Implementations are invoked from an arbitrary engine thread and MUST
 * be thread-safe (the Rust trait carries Send + Sync). A listener must
 * not throw across the boundary: a foreign exception (or a Rust panic
 * during dispatch) is caught by the engine's panic shield and logged;
 * the dispatch thread survives.
 */
public interface EngineEventListener {
    
    /**
     * One coalesced snapshot with a strictly monotonic `rev`.
     */
    fun `onEngineEvent`(`snapshot`: EngineSnapshot)
    
    companion object
}

// Magic number for the Rust proxy to call using the same mechanism as every other method,
// to free the callback once it's dropped by Rust.
internal const val IDX_CALLBACK_FREE = 0
// Callback return codes
internal const val UNIFFI_CALLBACK_SUCCESS = 0
internal const val UNIFFI_CALLBACK_ERROR = 1
internal const val UNIFFI_CALLBACK_UNEXPECTED_ERROR = 2

/**
 * @suppress
 */
public abstract class FfiConverterCallbackInterface<CallbackInterface: Any>: FfiConverter<CallbackInterface, Long> {
    internal val handleMap = UniffiHandleMap<CallbackInterface>()

    internal fun drop(handle: Long) {
        handleMap.remove(handle)
    }

    override fun lift(value: Long): CallbackInterface {
        return handleMap.get(value)
    }

    override fun read(buf: ByteBuffer) = lift(buf.getLong())

    override fun lower(value: CallbackInterface) = handleMap.insert(value)

    override fun allocationSize(value: CallbackInterface) = 8UL

    override fun write(value: CallbackInterface, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}

